                        let vpn1 = ((va >> 21) & 0x1FF) as usize;
                        let vpn0 = ((va >> 12) & 0x1FF) as usize;

                        let Some(root_table) = PtTable::from_phys(self.pgd << PAGE_SHIFT) else {
                            va += PAGE_SIZE_USIZE as u64;
                            continue;
                        };
