            /// (freshly allocated, or the PTE-locked walk targets of the
            /// fork/COW paths, whose exclusion argument the callers own).
            #[inline]
            pub fn from_phys_live(phys: u64) -> Option<PtTable> {
                Self::from_phys(phys)
            }

